 private static int[] widths(JSONArray rows)throws Exception {int cols=rows.getJSONArray(0).length();int[] result=new int[cols];Arrays.fill(result,12);for(int r=0;r<Math.min(rows.length(),500);r++){JSONArray row=rows.getJSONArray(r);for(int c=0;c<cols;c++)for(String line:row.optString(c,"").split("\n",-1))result[c]=Math.max(result[c],Math.min(44,DocumentLayout.visualLength(line)+3));}return result;}
